import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';

function ResetPassword() {
  const [newPassword, setNewPassword] = useState('');
  const [message, setMessage] = useState('');
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    const token = new URLSearchParams(location.search).get('token');
    if (!token) {
      setMessage('Invalid reset link');
      setTimeout(() => navigate('/login'), 2000);
    }
  }, [location, navigate]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    const token = new URLSearchParams(location.search).get('token');
    try {
      const response = await axios.post(`http://localhost:8000/verify?token=${token}`,
        new URLSearchParams({ password: newPassword }),
        { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } }
      );
      if (response.data.msg === 'Password reset successful') {
        setMessage('Password has been reset! You can now log in with your new password.');
        setTimeout(() => navigate('/login'), 2000);
      } else {
        setMessage('Failed to reset password. Please try again.');
      }
    } catch (error) {
      setMessage('An error occurred. Please try again.');
    }
  };

  return (
    <div>
      <h2>Set New Password</h2>
      <form onSubmit={handleSubmit}>
        <label htmlFor="newPassword">New Password:</label>
        <input
          type="password"
          id="newPassword"
          value={newPassword}
          onChange={(e) => setNewPassword(e.target.value)}
          required
        />

        <button type="submit">Set Password</button>
      </form>
      <p>{message}</p>
    </div>
  );
}

export default ResetPassword;
